mapper.select:
select t.tal_id as talentId, t.tal_status as status, t.tal_matched_score as matchedScore, t.tal_current_round as currentRound, t.tal_resume_id as resumeId, date_format(t.tal_updated_at, '%Y-%m-%d %H:%i') as updateTime, case when t.tal_status in (8, 9) then 1 when t.tal_status = 3 and exists (select 1 from t_tal_status_log sl where sl.tsl_candidate_id = t.tal_id and sl.tsl_to_status = 2) then 2 when t.tal_status = 3 then 4 when t.tal_archive_source = 3 then 3 else 0 end as archiveSource, u.user_id as userId, u.nick_name as name, u.phonenumber as phone, u.email as email, r.rbs_job_direction as jobDirection, (select group_concat(tg_name separator ',') from t_tal_tag where tg_candidate_id = t.tal_id) as tags from t_tal t left join sys_user u on u.user_id = t.tal_user_id left join t_res_base r on r.rbs_id = t.tal_resume_id where t.tal_company_id = #{companyId}
and t.tal_status = #{status}
and (u.nick_name like concat('%', #{keyword}, '%') or u.phonenumber like concat('%', #{keyword}, '%'))
and exists (select 1 from t_tal_tag tg where tg.tg_candidate_id = t.tal_id and tg.tg_name = #{tag})
and r.rbs_job_direction = #{direction}
and (case when t.tal_status in (8, 9) then 1 when t.tal_status = 3 and exists (select 1 from t_tal_status_log sl where sl.tsl_candidate_id = t.tal_id and sl.tsl_to_status = 2) then 2 when t.tal_status = 3 then 4 when t.tal_archive_source = 3 then 3 else 0 end) = #{archiveSource}
order by t.tal_id desc

select t.tal_id as talentId, t.tal_status as status, t.tal_matched_score as matchedScore, t.tal_current_round as currentRound, t.tal_resume_id as resumeId, date_format(t.tal_updated_at, '%Y-%m-%d %H:%i') as updateTime, case when t.tal_status in (8, 9) then 1 when t.tal_status = 3 and exists (select 1 from t_tal_status_log sl where sl.tsl_candidate_id = t.tal_id and sl.tsl_to_status = 2) then 2 when t.tal_status = 3 then 4 when t.tal_archive_source = 3 then 3 else 0 end as archiveSource, u.user_id as userId, u.nick_name as name, u.phonenumber as phone, u.email as email, r.rbs_job_direction as jobDirection, 2 as searchFilterVersion, education.highestEducation as highestEducation, experience.workMonths as workMonths, nullif(trim(u.current_city), '') as currentCity, nullif(trim(u.target_city), '') as targetCity, date_format(u.login_date, '%Y-%m-%d %H:%i:%s') as lastLoginTime, (select group_concat(tg_name separator ',') from t_tal_tag where tg_candidate_id = t.tal_id) as tags from t_tal t left join sys_user u on u.user_id = t.tal_user_id left join t_res_base r on r.rbs_id = t.tal_resume_id and r.rbs_user_id = t.tal_user_id and r.rbs_status = 1 left join ( select edu_resume_id as resumeId, max(case when edu_degree between 1 and 5 then edu_degree else null end) as highestEducation from t_res_education group by edu_resume_id ) education on education.resumeId = r.rbs_id left join ( select ordered.resumeId, sum(greatest(0, ordered.endMonth - greatest(ordered.startMonth, coalesce(ordered.previousEndMonth, ordered.startMonth)))) as workMonths from ( select currentWork.resumeId, currentWork.workId, currentWork.startMonth, currentWork.endMonth, max(previousWork.endMonth) as previousEndMonth from () currentWork left join () previousWork on previousWork.resumeId = currentWork.resumeId and (previousWork.startMonth < currentWork.startMonth or (previousWork.startMonth = currentWork.startMonth and previousWork.workId < currentWork.workId)) group by currentWork.resumeId, currentWork.workId, currentWork.startMonth, currentWork.endMonth ) ordered group by ordered.resumeId ) experience on experience.resumeId = r.rbs_id where t.tal_company_id = #{companyId}
and t.tal_status = #{status}
and (u.nick_name like concat('%', #{keyword}, '%') or u.phonenumber like concat('%', #{keyword}, '%'))
and exists (select 1 from t_tal_tag tg where tg.tg_candidate_id = t.tal_id and tg.tg_name = #{tag})
and r.rbs_job_direction = #{direction}
and (case when t.tal_status in (8, 9) then 1 when t.tal_status = 3 and exists (select 1 from t_tal_status_log sl where sl.tsl_candidate_id = t.tal_id and sl.tsl_to_status = 2) then 2 when t.tal_status = 3 then 4 when t.tal_archive_source = 3 then 3 else 0 end) = #{archiveSource}
and education.highestEducation >= #{criteria.minimumEducation}
and experience.workMonths >= #{criteria.minimumWorkMonths}
and experience.workMonths < #{criteria.maximumWorkMonths}
and trim(u.current_city) = #{criteria.city} and trim(u.target_city) = #{criteria.city}
and u.login_date >= #{criteria.loginSince} and u.login_date <= #{criteria.referenceTime}
order by t.tal_id desc

select a.app_id as applicationId, t.tal_id as talentId, t.tal_status as talentStatus, a.app_status as appStatus, (select cast(coalesce(json_extract(x.asr_report, '$.adjustedTotalScore'), json_extract(x.asr_report, '$.totalScore')) as decimal(6,1)) from t_ai_candidate_analysis x where x.asr_company_id = #{companyId} and x.asr_position_id = a.app_position_id and x.asr_candidate_id = t.tal_id order by x.asr_updated_at desc limit 1) as matchedScore, date_format(a.app_created_at, '%Y-%m-%d %H:%i') as appliedAt, date_format(a.app_updated_at, '%Y-%m-%d %H:%i') as updateTime, p.pos_id as positionId, p.pos_title as positionName, p.pos_work_city as city, u.user_id as userId, u.nick_name as name, u.phonenumber as phone, r.rbs_job_direction as jobDirection, (select o.ofr_status from t_off_offer o where o.ofr_candidate_id = t.tal_id and o.ofr_position_id = a.app_position_id order by o.ofr_id desc limit 1) as offerStatus, (select ps.psg_name from t_process_instance pi join t_process_stage ps on ps.psg_id = pi.pin_current_stage_id where pi.pin_candidate_id = t.tal_id and pi.pin_position_id = a.app_position_id order by pi.pin_id desc limit 1) as currentStage from t_app_record a join t_pos p on p.pos_id = a.app_position_id and p.pos_company_id = #{companyId} join t_tal t on t.tal_id = a.app_candidate_id and t.tal_company_id = #{companyId} left join sys_user u on u.user_id = t.tal_user_id left join t_res_base r on r.rbs_id = a.app_resume_id where 1 = 1
and a.app_position_id = #{positionId}
and a.app_status = #{status}
order by a.app_created_at desc, a.app_id desc

